import { ConflictError, ValidationError } from '../errors/DomainError';
import { DueDate } from '../value-objects/DueDate';
import { TaskStatus } from '../value-objects/TaskStatus';

export interface CreateTaskParams {
  id: string;
  projectId: string;
  title: string;
  description: string;
  dueDate?: DueDate | null;
  status?: TaskStatus;
}

export class Task {
  private constructor(
    readonly id: string,
    readonly projectId: string,
    readonly title: string,
    readonly description: string,
    readonly dueDate: DueDate | null,
    private currentStatus: TaskStatus,
    private currentAssigneeId: string | null,
  ) {}

  static create(params: CreateTaskParams): Task {
    const title = params.title.trim();
    if (title === '') {
      throw new ValidationError('Task title must not be empty');
    }
    return new Task(
      params.id,
      params.projectId,
      title,
      params.description,
      params.dueDate ?? null,
      params.status ?? TaskStatus.TODO,
      null,
    );
  }

  get status(): TaskStatus {
    return this.currentStatus;
  }

  get assigneeId(): string | null {
    return this.currentAssigneeId;
  }

  /**
   * Records the assignee. Callers must ensure the user exists;
   * use TaskAssignmentService rather than calling this directly.
   */
  assignTo(userId: string): void {
    this.currentAssigneeId = userId;
  }

  markDone(): void {
    if (this.currentStatus.isDone()) {
      throw new ConflictError(`Task "${this.id}" is already done`);
    }
    this.currentStatus = TaskStatus.DONE;
  }
}

=====SOURCE-END=====

